import { useForm } from 'react-hook-form';
import { yupResolver } from '@hookform/resolvers/yup';
import { TextField, Checkbox, FormControlLabel, Button, Box } from '@mui/material';
import schema from '../validations/formAppSchema';

export default function FormApp() {
  const { register, handleSubmit, formState: { errors } } = useForm({
    defaultValues: {
      name: '',
      email: '',
      title: '',
      message: '',
      agreement: false,
    },
    resolver: yupResolver(schema),
  });

  const onSubmit = data => console.log(data);
  const onError = err => console.log(err);

  return (
    <Box component="form" onSubmit={handleSubmit(onSubmit, onError)} noValidate sx={{ maxWidth: 500, mx: 'auto' }}>
      <TextField
        label="お名前"
        placeholder="山田 太郎"
        fullWidth
        margin="normal"
        error={!!errors.name}
        helperText={errors.name?.message}
        {...register('name')}
      />

      <TextField
        label="メールアドレス"
        placeholder="admin@example.com"
        type="email"
        fullWidth
        margin="normal"
        error={!!errors.email}
        helperText={errors.email?.message}
        {...register('email')}
      />

      <TextField
        label="件名"
        placeholder="お問い合わせの件名"
        fullWidth
        margin="normal"
        error={!!errors.title}
        helperText={errors.title?.message}
        {...register('title')}
      />

      <TextField
        label="本文"
        placeholder="お問い合わせ内容をご記入ください"
        fullWidth
        margin="normal"
        multiline
        rows={5}
        error={!!errors.message}
        helperText={errors.message?.message}
        {...register('message')}
      />

      <FormControlLabel
        control={<Checkbox {...register('agreement')} />}
        label="プライバシーポリシーに同意する"
      />
      {errors.agreement && (
        <Box sx={{ color: 'error.main', fontSize: 12 }}>{errors.agreement.message}</Box>
      )}

      <Button type="submit" variant="contained" sx={{ mt: 2 }}>
        送信
      </Button>
    </Box>
  );
}
